{
  "findings": [
    {
      "check_id": "AVD-AWS-0178",
      "title": "VPC Flow Logs is not enabled for VPC",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "The VPC does not have flow logs enabled. Without flow logs, you risk not having enough information about network traffic flow to investigate incidents or identify security issues."
    }
  ],
  "patched_code": "resource "aws_vpc" "changeme_aws_vpc_simple" {
  cidr_block = "10.1.0.0/16"

  tags = {
    Name = "changeme_aws_vpc_simple"
  }
}

resource "aws_flow_log" "changeme_vpc_flow_log" {
  log_destination      = "arn:aws:logs:us-east-1:123456789012:log-group:my-vpc-flow-logs"
  log_destination_type = "cloud-watch-logs"
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.changeme_aws_vpc_simple.id

  depends_on = [aws_vpc.changeme_aws_vpc_simple]
}",
  "fix_summary": "Enabled VPC Flow Logs for the VPC by adding an `aws_flow_log` resource to capture all traffic and send logs to CloudWatch."
}
